import{_ as a,o as e,c as i,a3 as o}from"./chunks/framework.BZCmpA0A.js";const S=JSON.parse('{"title":"Spec 13：螢光色塊開機字樣","description":"","frontmatter":{},"headers":[],"relativePath":"SPEC-13-block-splash.md","filePath":"SPEC-13-block-splash.md","lastUpdated":1793080235000}'),r={name:"SPEC-13-block-splash.md"};function t(s,l,h,c,n,p){return e(),i("div",null,[...l[0]||(l[0]=[o('<h1 id="spec-13-螢光色塊開機字樣" tabindex="-1">Spec 13：螢光色塊開機字樣 <a class="header-anchor" href="#spec-13-螢光色塊開機字樣" aria-label="Permalink to &quot;Spec 13：螢光色塊開機字樣&quot;">​</a></h1><p>後續使用者於 2026-10-27 要求更新 AGENTS.md：確認實作符合預期後即可直接 commit／push。本功能已獲使用者驗收，依新規則連同文件與協作規則提交；下方不提交的敘述保留實作當時紀錄。</p><h2 id="目標與範圍" tabindex="-1">目標與範圍 <a class="header-anchor" href="#目標與範圍" aria-label="Permalink to &quot;目標與範圍&quot;">​</a></h2><p>使用者希望 PowerShell 的 QEMU 開機畫面有彩色 WUWAOS，字體為實心粗筆畫，不再用井字號／星號拼出。保留中央向左右展開，限至少 80 欄、支援 ANSI 256 色的終端。不新增測試程式碼、不自行 commit／push／部署網站。</p><h2 id="設計與演算法" tabindex="-1">設計與演算法 <a class="header-anchor" href="#設計與演算法" aria-label="Permalink to &quot;設計與演算法&quot;">​</a></h2><ul><li>kernel/splash.c 保存 W／U／A／O／S 的 5×7 bitmap（位元字形），每列用五個 bit 指定填色位置；字母索引組成 WUWAOS。</li><li>每個點橫向占兩個空格，用 ANSI background color（背景色）畫出連續色塊，不輸出星號、井字號或依賴 UTF-8 的實心方塊字元，因此不需改 PowerShell 編碼或安裝字型。</li><li>字母間留兩欄，總寬 70 欄，80 欄終端左側留白 5 欄。七行從螢光黃綠漸變到薄荷綠。</li><li>半徑從 1 到 35，每格只填入中央遮罩內的有效像素；遮罩外與字形空洞輸出預設背景空格。僅填色狀態改變時發出控制碼，行尾重設顏色，避免下方核心訊息被染色。</li><li>使用既有 rdtime／10 MHz 時基，每格 32 ms、最後停留 200 ms，預定等待 1320 ms，另加序列輸出時間。結束重設顏色並恢復游標。</li><li>每格 O(H×W)，H=7、W=70；字形資料與額外空間固定，沒有動態記憶體配置。這是終端色塊字，不是圖片、GUI 或字型檔。</li></ul><h2 id="步驟與驗收" tabindex="-1">步驟與驗收 <a class="header-anchor" href="#步驟與驗收" aria-label="Permalink to &quot;步驟與驗收&quot;">​</a></h2><ol><li>替換舊字形與逐欄繪製，保留啟動呼叫位置。</li><li>建置並於 PowerShell 的實際 QEMU 終端檢查顏色、字樣、動畫位置與 shell 顏色還原。</li><li>更新 README、CODE_GUIDE 與歷史索引，記錄已驗證與限制。</li></ol><h2 id="驗收紀錄" tabindex="-1">驗收紀錄 <a class="header-anchor" href="#驗收紀錄" aria-label="Permalink to &quot;驗收紀錄&quot;">​</a></h2><p>2026-10-27：</p><ul><li>make 通過 -Wall/-Wextra/-Werror，kernel.elf 無未解析符號。</li><li>以實際 QEMU 序列輸出日誌 build/block-splash.log 確認 35 格定點重繪、螢光綠背景控制碼與最終 wuwaos&gt; 提示；使用既有獨立驗證磁碟，WUFS 設 readonly，不更動使用者原有磁碟。</li><li>使用者在實際檢查後明確回覆「已檢查通過」，作為字形、配色與畫面效果的使用者驗收。代理的桌面工具限制 PowerShell 操控，未自行取得原生視窗截圖，不把序列日誌當作目視證據。</li><li>80 欄布局由固定 70 欄字樣與 5 欄左側留白構成；結束輸出顏色重設與游標恢復。不宣稱已驗證非 ANSI 256 色終端、小於 80 欄或其他平台時基。</li><li>沒有新增測試程式碼、修改 OS 其他子系統、commit／push 或公開網站部署。舊 ASCII 動畫紀錄保留於 Spec 04。</li></ul>',11)])])}const m=a(r,[["render",t]]);export{S as __pageData,m as default};
